// The user is the connection's, never the frame's: a client names no one's list but its own.
async function handleListSessions(
  ws: WebSocket,
  session: ChatSession,
  sessionStore: SessionStore,
  message: ListSessionsMessage
): Promise<void> {
  try {
    const summaries = (await sessionStore.listFor?.(session.userId, {limit: message.limit, before: message.before})) ?? [];
